import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../../core/theme.dart';
import '../../models/expense_model.dart';
import '../../models/user_model.dart';
import '../../services/firestore_service.dart';
import '../../widgets/common.dart';
import '../../widgets/expense_tile.dart';

class UserDetailScreen extends StatefulWidget { final AppUser user; const UserDetailScreen({super.key,required this.user}); @override State<UserDetailScreen> createState()=>_UserDetailScreenState(); }
class _UserDetailScreenState extends State<UserDetailScreen>{int tab=0;
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('User details',style:TextStyle(fontWeight:FontWeight.w700))),body:StreamBuilder<List<Expense>>(stream:FirestoreService().userExpenses(widget.user.uid),builder:(context,snap){final all=snap.data??[];final list=_filter(all);final total=list.fold<double>(0,(s,e)=>s+e.amount);return SingleChildScrollView(padding:const EdgeInsets.fromLTRB(20,8,20,30),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(width:double.infinity,padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[AppColors.primary,AppColors.secondary]),borderRadius:BorderRadius.circular(24)),child:Row(children:[CircleAvatar(radius:28,backgroundColor:Colors.white.withValues(alpha:.18),child:Text((widget.user.name.isNotEmpty?widget.user.name[0]:'U').toUpperCase(),style:const TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.w800))),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.user.name,style:const TextStyle(color:Colors.white,fontSize:19,fontWeight:FontWeight.w800)),const SizedBox(height:5),Text(widget.user.email,style:const TextStyle(color:Colors.white70,fontSize:12.5)),const SizedBox(height:3),Text(widget.user.phone,style:const TextStyle(color:Colors.white70,fontSize:12))]))])),const SizedBox(height:18),Container(width:double.infinity,padding:const EdgeInsets.all(17),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20),border:Border.all(color:AppColors.border)),child:Column(children:[_info('Registration date',widget.user.createdAt==null?'—':DateFormat('dd MMMM yyyy, hh:mm a').format(widget.user.createdAt!)),const Divider(height:24),_info('Role',widget.user.role),const Divider(height:24),_info('Selected period',_label()),const Divider(height:24),_info('Total', '₹${NumberFormat('#,##0.00').format(total)}')])),const SizedBox(height:22),_tabs(),const SizedBox(height:14),if(list.isEmpty)const EmptyState(title:'No expenses',message:'This user has no expenses in the selected period.') else ...list.map((e)=>ExpenseTile(expense:e)),]));}));
 Widget _info(String a,String b)=>Row(children:[Expanded(child:Text(a,style:const TextStyle(color:AppColors.slate,fontSize:12.5))),Text(b,style:const TextStyle(fontWeight:FontWeight.w700,fontSize:12.5))]);
 Widget _tabs()=>Container(padding:const EdgeInsets.all(4),decoration:BoxDecoration(color:const Color(0xFFEFF3F8),borderRadius:BorderRadius.circular(15)),child:Row(children:List.generate(3,(i){final l=['Today','This Week','This Month'][i];return Expanded(child:GestureDetector(onTap:()=>setState(()=>tab=i),child:AnimatedContainer(duration:const Duration(milliseconds:180),padding:const EdgeInsets.symmetric(vertical:11),decoration:BoxDecoration(color:tab==i?Colors.white:Colors.transparent,borderRadius:BorderRadius.circular(12)),child:Text(l,textAlign:TextAlign.center,style:TextStyle(fontSize:12,fontWeight:tab==i?FontWeight.w800:FontWeight.w600,color:tab==i?AppColors.primary:AppColors.slate)))));})));
 List<Expense> _filter(List<Expense>x){final n=DateTime.now();if(tab==0)return x.where((e)=>e.expenseDate.year==n.year&&e.expenseDate.month==n.month&&e.expenseDate.day==n.day).toList();if(tab==1){final s=DateTime(n.year,n.month,n.day).subtract(Duration(days:n.weekday-1));return x.where((e)=>!e.expenseDate.isBefore(s)&&e.expenseDate.isBefore(s.add(const Duration(days:7)))).toList();}return x.where((e)=>e.expenseDate.year==n.year&&e.expenseDate.month==n.month).toList();}String _label()=>['Today','Current week','Current month'][tab];
}
